{
  "packs": [
    {
      "id": "basics",
      "version": "60924.1",
      "config": {
        "barriers": {
          "rules": [
            {
              "between": [
                "server",
                "extension"
              ],
              "allow": [
                "shared"
              ],
              "reason": "the extension and its server integrate only through shared/ (the vendored single-source of categories/normalizeUrl) and the HTTP contract — never by referencing each other's code"
            }
          ]
        }
      }
    },
    {
      "id": "chrome-extension",
      "version": "60922.4"
    },
    {
      "id": "executable-requirements",
      "version": "60922.1"
    },
    {
      "id": "git-github",
      "version": "60922.5"
    },
    {
      "id": "node",
      "version": "60922.1"
    },
    {
      "id": "spec-driven-product",
      "version": "60922.2"
    },
    {
      "id": "claudinite-growth",
      "version": "60924.1"
    },
    "local/tldr",
    {
      "id": "claude-code-web-users-support",
      "version": "60924.1",
      "config": {
        "repo": "missingbulb/Shepherd"
      }
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60924.1"
    },
    {
      "id": "claudinite-tasks",
      "version": "60923.3"
    }
  ],
  "accept": [
    {
      "rule": "barrier",
      "path": "server/README.md",
      "reason": "the server's deploy/OAuth guide documents how the two halves relate (the extension manifest key, config.mjs client id, `cd ../extension` build) — cross-cutting setup docs, not a code coupling; the server ships no import of extension code"
    },
    {
      "rule": "barrier",
      "path": "extension/src/api.mjs",
      "reason": "a comment notes the server must allow X-Client-Version in CORS (template.yaml AllowHeaders) — documentation of the HTTP contract, not a code reference into server/"
    },
    {
      "rule": "claudinite-isolation",
      "path": "CLAUDE.md",
      "reason": "orientation prose only — the router names where the vendored canon lives so a reader knows the guidance is injected, not authored here; no code or content in this repo depends on the path"
    },
    {
      "rule": "claudinite-isolation",
      "path": "dev/procedures/working-instructions.md",
      "reason": "same orientation pointer — the working-instructions router says the general discipline is auto-injected from the vendored corpus rather than restated here, which is the sentence that stops the doc duplicating canon prose"
    }
  ],
  "sharedConstants": [
    {
      "what": "the extension version, carried in three JSON files that can't share an import: extension/manifest.json is the shipped, user-visible number; extension/package.json is the npm record the release config names as package_json_path; the repo-root package.json is what cer/version-sync reads by name. The daily auto-release bumps all three in one commit (the two release-config paths via .github/actions/bump-extension-patch, the root file via the align step in chrome-extension-daily-release.yml), so any disagreement here means a bump landed in some files but not all",
      "regex": true,
      "value": "\"version\": \"\\d+\\.\\d+\\.\\d+\"",
      "counts": {
        "extension/manifest.json": 1,
        "extension/package.json": 1,
        "package.json": 1
      }
    }
  ],
  "taskScheduler": {
    "agenticTaskInvocationEndpoints": {
      "default": {

